import json
def repair(s):
    if not isinstance(s,str): return s
    try: return s.encode('cp437').decode('utf-8')
    except Exception: return s
def walk(o):
    if isinstance(o,str): return repair(o)
    if isinstance(o,list): return [walk(x) for x in o]
    if isinstance(o,dict): return {k:walk(v) for k,v in o.items()}
    return o
def proj(p,fix=False):
    d=json.load(open(p,encoding='utf-8-sig'))
    ps=d.get('projects',d) if isinstance(d,dict) else d
    if fix: ps=walk(ps)
    return {x.get('name'):x for x in ps}
live=proj('portfolio.json')
bad=[]
for src in ['portfolio.json.from-mac','portfolio.json.from-windows']:
    o=proj(src,fix=True)
    for name,p in o.items():
        lv=live.get(name)
        if lv is None: bad.append((src,name,"PROJECT MISSING")); continue
        lset={json.dumps(u,sort_keys=True) for u in lv.get('updates',[])}
        miss=[u for u in p.get('updates',[]) if json.dumps(u,sort_keys=True) not in lset]
        if miss: bad.append((src,name,f"{len(miss)} still missing",[str(m)[:120] for m in miss]))
print("AFTER MOJIBAKE REPAIR -> LOST DATA:", json.dumps(bad,indent=1) if bad else "NONE. live is a full superset.")
PY

